3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner &amp; OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public abstract class OwnerMapper {
22	
23	    @Autowired
24	    protected OwnerRepository ownerRepository;
25	
26	    @Mapping(target = "displayName",
27	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials",
29	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "membershipPoints",
31	            expression = "java(membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel",
33	            expression = "java(membershipLevel(owner))")
34	    @Mapping(target = "locality",
35	            expression = "java(org.springframework.samples.petclinic.rest.function.common.Localities.regionOf(owner.getCustomerCode()))")
36	    @Mapping(target = "timezone",
37	            expression = "java(org.springframework.samples.petclinic.rest.function.common.Localities.timezoneOf(owner.getCustomerCode()))")
38	    @Mapping(target = "contactPreference",
39	            expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey",
41	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.of(owner))")
42	    @Mapping(target = "checkDigit",
43	            expression = "java(checkDigit(owner))")
44	    @Mapping(target = "telephoneDisplay",
45	            expression = "java(telephoneDisplay(owner))")
46	    @Mapping(target = "ageBand",
47	            expression = "java(ageBand(owner))")
48	    @Mapping(target = "bulkSignupWarning", ignore = true)
49	    public abstract OwnerDto toOwnerDto(Owner owner);
50	
51	    public abstract Owner toOwner(OwnerDto ownerDto);
52	
53	    @Mapping(target = "id", ignore = true)
54	    @Mapping(target = "pets", ignore = true)
55	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
56	
57	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
58	
59	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
60	
61	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
62	        OwnerPageDto ownerPageDto = new OwnerPageDto();
63	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
64	        ownerPageDto.setPage(ownerPage.getNumber());
65	        ownerPageDto.setSize(ownerPage.getSize());
66	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
67	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
68	        return ownerPageDto;
69	    }
70	
71	    /**
72	     * Score the owner's membership points. Starts at 0, plus 2 when an email is present, plus 1
73	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more owners, plus 3 when
74	     * tenure exceeds 365 days. Because a newly created owner has zero tenure, the tenure points
75	     * are only earned on later reads.
76	     */
77	    protected Integer membershipPoints(Owner owner) {
78	        int points = 0;
79	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
80	            points += 2;
81	        }
82	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount().intValue() == 0) {
83	            points += 1;
84	        }
85	        if (householdSize(owner) >= 3) {
86	            points += 2;
87	        }
88	        if (owner.getRegistrationDate() != null
89	                && java.time.temporal.ChronoUnit.DAYS.between(owner.getRegistrationDate(),
90	                        java.time.LocalDate.now()) > 365) {
91	            points += 3;
92	        }
93	        return points;
94	    }
95	
96	    /**
97	     * Map {@link #membershipPoints(Owner)} to a membership level from 1 to 4: level 1 for 0-1
98	     * points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
99	     */
100	    protected Integer membershipLevel(Owner owner) {
101	        int points = membershipPoints(owner);
102	        if (points <= 1) {
103	            return 1;
104	        }
105	        if (points <= 3) {
106	            return 2;
107	        }
108	        if (points <= 5) {
109	            return 3;
110	        }
111	        return 4;
112	    }
113	
114	    /**
115	     * The number of owners in this owner's household, identified by the shared {@code householdId}
116	     * assigned at creation. An owner with no householdId counts only as itself.
117	     */
118	    protected long householdSize(Owner owner) {
119	        String householdId = owner.getHouseholdId();
120	        if (householdId == null) {
121	            return 1;
122	        }
123	        long count = 0;
124	        for (Owner existing : ownerRepository.findAll()) {
125	            if (householdId.equals(existing.getHouseholdId())) {
126	                count++;
127	            }
128	        }
129	        return count;
130	    }
131	
132	    /**
133	     * Derive the owner's preferred contact channel: {@code EMAIL} when an email is present,
134	     * otherwise {@code PHONE}.
135	     */
136	    protected String contactPreference(Owner owner) {
137	        return (owner.getEmail() != null && !owner.getEmail().isEmpty()) ? "EMAIL" : "PHONE";
138	    }
139	
140	    /**
141	     * Derive the owner's age band from {@code birthDate} as at {@code registrationDate}:
142	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, {@code SENIOR} at 65 or over.
143	     * Returns {@code null} when no birth date was supplied.
144	     */
145	    protected String ageBand(Owner owner) {
146	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
147	            return null;
148	        }
149	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
150	        if (age < 18) {
151	            return "MINOR";
152	        }
153	        if (age < 65) {
154	            return "ADULT";
155	        }
156	        return "SENIOR";
157	    }
158	
159	    /**
160	     * Known country codes (digits after the {@code '+'}), longest first so {@code '61'} is
161	     * matched before {@code '1'}, mirroring {@code NormalizeOwnerTelephone}.
162	     */
163	    private static final String[] COUNTRY_CODES = {"61", "1"};
164	
165	    /**
166	     * Format the stored E.164 telephone for humans: the country code, a space, then the national
167	     * digits grouped in threes from the left (e.g. {@code +61412345678} -> {@code +61 412 345 678}).
168	     * Returns the raw value unchanged when it is not a recognised E.164 number.
169	     */
170	    protected String telephoneDisplay(Owner owner) {
171	        String telephone = owner.getTelephone();
172	        if (telephone == null || !telephone.startsWith("+")) {
173	            return telephone;
174	        }
175	        String digits = telephone.substring(1);
176	        String code = null;
177	        for (String candidate : COUNTRY_CODES) {
178	            if (digits.startsWith(candidate)) {
179	                code = candidate;
180	                break;
181	            }
182	        }
183	        if (code == null) {
184	            return telephone;
185	        }
186	        String national = digits.substring(code.length());
187	        StringBuilder grouped = new StringBuilder("+").append(code);
188	        for (int i = 0; i < national.length(); i += 3) {
189	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
190	        }
191	        return grouped.toString();
192	    }
193	
194	    /**
195	     * Compute a single Luhn check digit (0-9) over the digits contained in the owner's
196	     * {@code customerCode}. Non-digit characters (such as the hyphen separators) are ignored.
